"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass


_VERSION_RE = re.compile(
    r"^(?P<major>0|[1-9]\d*)"
    r"\.(?P<minor>0|[1-9]\d*)"
    r"\.(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_COMPARATOR_RE = re.compile(r"^(<=|>=|<|>|=|\^|~)?(.+)$")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")
    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    prerelease = match.group("prerelease")
    build = match.group("build")
    return Version(
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        tuple(prerelease.split(".")) if prerelease is not None else (),
        tuple(build.split(".")) if build is not None else (),
    )


def _coerce(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _compare(a: Version, b: Version) -> int:
    for left, right in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if left != right:
            return -1 if left < right else 1

    if a.prerelease and not b.prerelease:
        return -1
    if b.prerelease and not a.prerelease:
        return 1

    for left, right in zip(a.prerelease, b.prerelease):
        left_numeric = left.isdigit()
        right_numeric = right.isdigit()
        if left_numeric and right_numeric:
            left_value = int(left)
            right_value = int(right)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        elif left != right:
            return -1 if left < right else 1

    if len(a.prerelease) != len(b.prerelease):
        return -1 if len(a.prerelease) < len(b.prerelease) else 1
    return 0


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare(_coerce(a), _coerce(b))


def _parse_comparator(token: str) -> list[tuple[str, Version]]:
    match = _COMPARATOR_RE.match(token)
    if match is None:
        raise ValueError(f"invalid comparator: {token!r}")

    operator = match.group(1) or "="
    version = parse(match.group(2))

    if operator == "^":
        if version.major != 0:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor != 0:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return [(">=", version), ("<", upper)]

    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return [(">=", version), ("<", upper)]

    return [(operator, version)]


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    sets: list[list[tuple[str, Version]]] = []
    for part in range_.split("||"):
        part = part.strip()
        if not part:
            raise ValueError(f"invalid range: {range_!r}")

        comparators: list[tuple[str, Version]] = []
        for token in part.split():
            comparators.extend(_parse_comparator(token))
        sets.append(comparators)
    return sets


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    # Pre-releases only match a set that explicitly mentions a pre-release
    # on the same MAJOR.MINOR.PATCH.
    if version.prerelease:
        allowed = any(
            candidate.prerelease
            and (candidate.major, candidate.minor, candidate.patch)
            == (version.major, version.minor, version.patch)
            for _, candidate in comparators
        )
        if not allowed:
            return False

    for operator, candidate in comparators:
        result = _compare(version, candidate)
        if operator == "=" and result != 0:
            return False
        if operator == ">" and result <= 0:
            return False
        if operator == ">=" and result < 0:
            return False
        if operator == "<" and result >= 0:
            return False
        if operator == "<=" and result > 0:
            return False
    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed = _coerce(version)
    return any(
        _satisfies_set(parsed, comparators)
        for comparators in _parse_range(range_)
    )

"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import re
from datetime import datetime, timedelta

_MONTH_NAMES = {
    name: number
    for number, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}

_DOW_NAMES = {
    name: number
    for number, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}

_VALUE_RE = re.compile(r"^\d+$")


class _Field:
    def __init__(self, name, minimum, maximum, names=None):
        self.name = name
        self.minimum = minimum
        self.maximum = maximum
        self.names = names or {}


_MINUTE = _Field("minute", 0, 59)
_HOUR = _Field("hour", 0, 23)
_DOM = _Field("day of month", 1, 31)
_MONTH = _Field("month", 1, 12, _MONTH_NAMES)
_DOW = _Field("day of week", 0, 7, _DOW_NAMES)


def _parse_value(text: str, field: _Field) -> int:
    if _VALUE_RE.match(text):
        value = int(text)
    else:
        value = field.names.get(text.upper(), -1)
    if value < field.minimum or value > field.maximum:
        raise ValueError(f"invalid {field.name}: {text!r}")
    return value


def _parse_item(item: str, field: _Field) -> set[int]:
    if not item:
        raise ValueError(f"invalid {field.name} item: {item!r}")

    if "/" in item:
        if item.count("/") != 1:
            raise ValueError(f"invalid {field.name} item: {item!r}")
        base, step_text = item.split("/")
        if not _VALUE_RE.match(step_text):
            raise ValueError(f"invalid {field.name} step: {step_text!r}")
        step = int(step_text)
        if step <= 0:
            raise ValueError(f"invalid {field.name} step: {step_text!r}")
        has_step = True
    else:
        base = item
        step = 1
        has_step = False

    if base == "*":
        start = field.minimum
        end = field.maximum
    elif "-" in base:
        if base.count("-") != 1:
            raise ValueError(f"invalid {field.name} item: {item!r}")
        start_text, end_text = base.split("-")
        start = _parse_value(start_text, field)
        end = _parse_value(end_text, field)
        if start > end:
            raise ValueError(f"invalid {field.name} range: {base!r}")
    else:
        start = _parse_value(base, field)
        end = field.maximum if has_step else start

    values = set(range(start, end + 1, step))
    if field is _DOW and 7 in values:
        values.remove(7)
        values.add(0)
    return values


def _parse_field(text: str, field: _Field) -> frozenset[int]:
    values: set[int] = set()
    for item in text.split(","):
        values.update(_parse_item(item, field))
    return frozenset(values)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    parts = expression.split()
    if len(parts) != 5:
        raise ValueError("cron expression must have five fields")

    minutes = _parse_field(parts[0], _MINUTE)
    hours = _parse_field(parts[1], _HOUR)
    days = _parse_field(parts[2], _DOM)
    months = _parse_field(parts[3], _MONTH)
    weekdays = _parse_field(parts[4], _DOW)

    dom_restricted = parts[2] != "*"
    dow_restricted = parts[4] != "*"

    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=365 * 5)

    while candidate <= limit:
        if candidate.month not in months:
            if candidate.month == 12:
                candidate = candidate.replace(
                    year=candidate.year + 1,
                    month=1,
                    day=1,
                    hour=0,
                    minute=0,
                )
            else:
                candidate = candidate.replace(
                    month=candidate.month + 1,
                    day=1,
                    hour=0,
                    minute=0,
                )
            continue

        dom_match = candidate.day in days
        dow_match = (candidate.isoweekday() % 7) in weekdays
        if dom_restricted and dow_restricted:
            day_matches = dom_match or dow_match
        else:
            day_matches = dom_match and dow_match

        if not day_matches:
            candidate = (candidate + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if candidate.hour not in hours:
            candidate = (candidate.replace(minute=0) + timedelta(hours=1))
            continue

        if candidate.minute not in minutes:
            candidate += timedelta(minutes=1)
            continue

        return candidate

    raise ValueError(f"no matching time within five years: {expression!r}")

"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"^:?-+:?$")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    extra = width - len(text)
    if align == "right":
        return " " * extra + text
    if align == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter_cell(width: int, align: str | None) -> str:
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    column_count = len(header)
    if align is None:
        alignments = [None] * column_count
    else:
        alignments = list(align)
        if len(alignments) != column_count:
            raise ValueError("align must have one entry per column")
        if any(value not in _ALIGNMENTS for value in alignments):
            raise ValueError("invalid alignment")

    header_cells = [_cell_text(value) for value in header]
    row_cells = []
    for row in rows:
        if len(row) > column_count:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (column_count - len(cells)))
        row_cells.append(cells)

    widths = []
    for index in range(column_count):
        width = len(header_cells[index])
        for cells in row_cells:
            width = max(width, len(cells[index]))
        widths.append(max(3, width))

    lines = [
        "| "
        + " | ".join(
            _pad(header_cells[index], widths[index], alignments[index])
            for index in range(column_count)
        )
        + " |"
    ]
    lines.append(
        "| "
        + " | ".join(
            _delimiter_cell(widths[index], alignments[index])
            for index in range(column_count)
        )
        + " |"
    )
    for cells in row_cells:
        lines.append(
            "| "
            + " | ".join(
                _pad(cells[index], widths[index], alignments[index])
                for index in range(column_count)
            )
            + " |"
        )
    return "\n".join(lines)


def _split_row(line: str) -> list[str]:
    line = line.strip()
    cells: list[str] = []
    buffer: list[str] = []
    leading_pipe = line.startswith("|")
    trailing_pipe = False
    index = 0

    while index < len(line):
        character = line[index]
        if character == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            buffer.append("|")
            index += 2
            trailing_pipe = False
        elif character == "|":
            cells.append("".join(buffer).strip())
            buffer = []
            index += 1
            trailing_pipe = True
        else:
            buffer.append(character)
            index += 1
            trailing_pipe = False

    cells.append("".join(buffer).strip())
    if leading_pipe:
        cells.pop(0)
    if trailing_pipe:
        cells.pop()
    return cells


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table: fewer than two lines")

    header = _split_row(lines[0])
    delimiter = _split_row(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has the wrong number of cells")

    alignments: list[str | None] = []
    for cell in delimiter:
        if not _DELIMITER_RE.match(cell):
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left = cell.startswith(":")
        right = cell.endswith(":")
        if left and right:
            alignments.append("center")
        elif left:
            alignments.append("left")
        elif right:
            alignments.append("right")
        else:
            alignments.append(None)

    rows = []
    for line in lines[2:]:
        cells = _split_row(line)
        if len(cells) != len(header):
            raise ValueError("row has the wrong number of cells")
        rows.append(cells)

    return header, rows, alignments

